code_sketch:
enum Shape { case circle(Double); case square(Double) }

func collide(_ a: Shape, _ b: Shape) -> String {
    switch (a, b) {
    case let (.circle(r), .square(s)): return "circle \(r) vs square \(s)"
    case let (.square, .circle):       return collide(b, a)   // canonicalise symmetric pairs
    case (.circle, .circle):           return "two circles"
    case (.square, .square):           return "two squares"
    }
}

