protocol ShapeVisitor {
    func visit(circle: Circle)
    func visit(square: Square)
}
protocol Shape { func accept(_ v: ShapeVisitor) }

struct Circle: Shape {
    let radius: Double
    func accept(_ v: ShapeVisitor) { v.visit(circle: self) }   // dispatch #2 target
}
